-- Capas (reparto del 15-10). Las del concurso (1, 17, 18) quedan sin capa: en pausa.
update ideas set capa = 1 where numero in (4, 14, 15, 16, 19, 20);
update ideas set capa = 2 where numero in (5, 12, 13, 23, 24, 25);
update ideas set capa = 3 where numero in (2, 3);
update ideas set capa = 4 where numero in (6, 7, 8, 9, 10, 11, 21, 22);
update ideas set version = '2.0' where version in ('1.3.3', '1.3.4', '1.4.0', 'Web', 'Operación');
